insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-mister-aguila', 'Peluche Mister Águila', 'Un águila con un aire travieso para darle un nuevo compañero a tu perro. Su cuello largo con textura de escamas contrasta con la cabeza y el cuerpo de peluche, mientras las alas estampadas completan el personaje. Un diseño para explorar y llevar de una aventura a la siguiente.', '22 x 34 cm de alto', (select id from public.categories where slug = 'peluches-peluches-alargados'), 'Talla', false, 0) on conflict (slug) do nothing;
