insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('collar-para-gatos-flores-delicadas', 'Collar para Gatos Flores Delicadas', 'Las flores en tonos morados crean un diseño delicado y elegante que resalta sin ser exagerado. Incluye cascabel y argolla para que puedas completar el collar con su placa de identificación.', null, (select id from public.categories where slug = 'gatos-collares-para-gato'), 'Talla', false, 10) on conflict (slug) do nothing;
