insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('collar-para-gatos-happy-cats', 'Collar para Gatos Happy Cats', 'Colorido, alegre y tan simpático como su nombre. El estampado de gatos felices está disponible en varios tonos e incluye cascabel y argolla para que puedas personalizarlo con su placa de identificación. Colores: Naranja 🟠 Morado 🟣 Rosado 🩷 Rojo ❤️ Azul 🔵 Verde 🟢', null, (select id from public.categories where slug = 'gatos-collares-para-gato'), 'Talla', false, 20) on conflict (slug) do nothing;
