insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('correa-collar-extreme-solida-azul', 'Correa & Collar Extreme Sólida Azul', 'Un collar sencillo, resistente y con colores que se hacen notar. Está pensado para acompañar a tu perro todos los días con un ajuste cómodo y un estilo fácil de combinar. Disfruta el paseo con una correa firme, cómoda de llevar y llena de color. Su diseño sólido combina con el collar Extreme y te ayuda a mantener a tu perro cerca con mayor confianza.', null, (select id from public.categories where slug = 'paseo-collares-y-correas-perros'), 'Talla', false, 30) on conflict (slug) do nothing;
