insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-mapache-alargado', 'Peluche Mapache Alargado', 'Su diseño de mapache alargado y su carita tierna lo convierten en un compañero divertido a la hora de jugar. Su cuerpo acanalado y sus extremidades suaves ofrecen diferentes texturas para explorar, mientras que su forma alargada facilita que los perros lo agarren, sacudan y lleven de un lado a otro. Un juguete ideal para esos peluditos que disfrutan de la compañía de un buen amigo durante sus momentos de juego.', '12 x 52 cm.', (select id from public.categories where slug = 'peluches-peluches-alargados'), 'Talla', false, 40) on conflict (slug) do nothing;
