insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('juguete-limon-en-tpr', 'Juguete Limón en TPR', 'Una tajada de limón para un perro que siempre quiere algo nuevo por explorar. Sus segmentos en relieve y el borde texturizado le dan distintas superficies para mordisquear. Está elaborado en TPR, incluye pito y puede congelarse para variar sus ratos de juego.', '11,5 cm', (select id from public.categories where slug = 'juguetes-juguetes-en-tpr'), 'Talla', false, 60) on conflict (slug) do nothing;
