insert into public.product_variants (product_id, size_label, price, display_order) select id, 'Collar talla M', 39800, 1 from public.products pr where slug = 'correa-collar-extreme-solida-rosada' and not exists (select 1 from public.product_variants x where x.product_id = pr.id and x.size_label = 'Collar talla M');
insert into public.product_variants (product_id, size_label, price, display_order) select id, 'Correa', 57800, 2 from public.products pr where slug = 'correa-collar-extreme-solida-rosada' and not exists (select 1 from public.product_variants x where x.product_id = pr.id and x.size_label = 'Correa');
insert into public.product_images (product_id, image_url, display_order) select id, '/imagenes/correa-collar-extreme-solida-rosada.jpg', 0 from public.products pr where slug = 'correa-collar-extreme-solida-rosada' and not exists (select 1 from public.product_images i where i.product_id = pr.id);
insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-paloma-hunter', 'Peluche Paloma Hunter', 'Para tu perro, una paloma de peluche puede ser el comienzo de un gran juego. Su cuerpo suave y alargado se acompaña de alas con estampado de plumas y pequeñas patas rosadas. Un diseño diferente para invitarlo a buscar su juguete y disfrutar un rato contigo.', '36,5 x 10 cm de alto', (select id from public.categories where slug = 'peluches-peluches-lisos'), 'Talla', false, 1140) on conflict (slug) do nothing;
insert into public.product_variants (product_id, size_label, price, display_order) select id, '', 46500, 0 from public.products pr where slug = 'peluche-paloma-hunter' and not exists (select 1 from public.product_variants x where x.product_id = pr.id and x.size_label = '');
insert into public.product_images (product_id, image_url, display_order) select id, '/imagenes/peluche-paloma-hunter.jpg', 0 from public.products pr where slug = 'peluche-paloma-hunter' and not exists (select 1 from public.product_images i where i.product_id = pr.id);
insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-coco-pet', 'Peluche Coco-pet', 'Un cocodrilo simpático para darle más variedad a sus juegos. Su cuerpo largo combina peluche suave con una zona amarilla de relieves marcados, mientras la cola y las pequeñas patas completan el diseño. Sus 54 cm lo convierten en un compañero que difícilmente pasará desapercibido en casa.', '20 x 54 cm de alto', (select id from public.categories where slug = 'peluches-otros-peluches'), 'Talla', false, 1150) on conflict (slug) do nothing;
insert into public.product_variants (product_id, size_label, price, display_order) select id, '', 46500, 0 from public.products pr where slug = 'peluche-coco-pet' and not exists (select 1 from public.product_variants x where x.product_id = pr.id and x.size_label = '');
insert into public.product_images (product_id, image_url, display_order) select id, '/imagenes/peluche-coco-pet.jpg', 0 from public.products pr where slug = 'peluche-coco-pet' and not exists (select 1 from public.product_images i where i.product_id = pr.id);
insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-zorro-alargado', 'Peluche Zorro alargado', 'Si tu perro aparece con un juguete en la boca para pedirte atención, este zorro puede convertirse en su nueva invitación a jugar. Tiene un cuerpo largo y acanalado, orejas grandes y una cola con punta blanca que le dan un aspecto simpático y lleno de movimiento.', '12 x 49,5 cm de alto', (select id from public.categories where slug = 'peluches-peluches-alargados'), 'Talla', false, 1160) on conflict (slug) do nothing;
