insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('arenera-doble-altura-con-pala-y-portapala-rosado-oscuro', 'Arenera doble altura con pala y portapala - Rosado oscuro', 'Una arenera sencilla y cómoda para acompañar sus primeros aprendizajes. La doble altura ayuda a contener mejor la arena y su formato abierto facilita el ingreso; además, viene con pala y portapala para tener todo a mano. Rosado Oscuro 🩷', '39 x 54 x 24 cm de alto', (select id from public.categories where slug = 'gatos-areneras'), 'Talla', false, 1170) on conflict (slug) do nothing;
