insert into public.product_images (product_id, image_url, display_order) select id, '/imagenes/arenera-doble-altura-con-pala-y-portapala-rosado-oscuro.jpg', 0 from public.products pr where slug = 'arenera-doble-altura-con-pala-y-portapala-rosado-oscuro' and not exists (select 1 from public.product_images i where i.product_id = pr.id);
insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('transportador-rel-morado', 'Transportador REL - Morado', 'Llevar a tu mascota contigo puede ser mucho más cómodo. Este transportador de tela tiene malla para favorecer la ventilación, bolsillo lateral y correa ajustable con almohadilla removible; los detalles reflectivos aportan un toque práctico durante el recorrido.', null, (select id from public.categories where slug = 'paseo-transportadores'), 'Tamaño', false, 1180) on conflict (slug) do nothing;
