insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-ciclope-azul', 'Peluche Cíclope Azul', 'Texturas diferentes hacen que el juego sea mucho más interesante. Este peluche combina tela con un anillo de goma para mordisquear, ofreciéndole a tu mascota otra forma de explorar, jugar y mantenerse entretenida.', '27 cm', (select id from public.categories where slug = 'peluches-otros-peluches'), 'Talla', false, 1190) on conflict (slug) do nothing;
