insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('peluche-dispensador-perezoso', 'Peluche dispensador Perezoso', 'Este perezoso tiene una expresión tranquila y una barriga que despierta la curiosidad. Su cuerpo suave incorpora un dispensador para colocar premios y darle a tu perro algo más por descubrir durante el juego. Una mezcla de ternura y diversión para acompañar sus momentos en casa.', '23 x 27 cm de alto', (select id from public.categories where slug = 'peluches-peluches-dispensador'), 'Talla', true, 1200) on conflict (slug) do nothing;
