insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('arenera-tom-azul', 'Arenera Tom - Azul', 'La hora de usar la arenera también puede tener estilo. Este modelo inspirado en Tom y Jerry tiene líneas sencillas, un acabado pulido y el tamaño apropiado para crear un rincón cómodo para tu gato sin recargar el espacio.', '38 x 13 x 36 cm', (select id from public.categories where slug = 'gatos-areneras'), 'Talla', false, 1210) on conflict (slug) do nothing;
