insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_featured, display_order) values ('bebedero-fuente-sweet', 'Bebedero Fuente Sweet', 'El agua en movimiento suele despertar su curiosidad y animarla a beber. La fuente Sweet tiene un flujo silencioso y doble filtro, ayudando a mantener el agua en circulación y con una sensación fresca durante el día.', null, (select id from public.categories where slug = 'comederos-comederos-y-bebederos'), 'Talla', false, 1220) on conflict (slug) do nothing;
